"use strict";(globalThis.webpackChunkgsf_docusaurus_template=globalThis.webpackChunkgsf_docusaurus_template||[]).push([[1708],{5936(e){e.exports=JSON.parse('{"tag":{"label":"storage","permalink":"/tags/storage","allTagsPath":"/tags","count":4,"items":[{"id":"development/data-handling/avoid-tracking-unnecessary-data","title":"Avoid tracking unnecessary data","description":"User tracking, user data collection and targeting in things like advertisements are responsible for significant energy use in many digital products, and services.","permalink":"/development/data-handling/avoid-tracking-unnecessary-data"},{"id":"operations/resource-lifecycle/delete-or-auto-expire-unused-storage","title":"Delete or auto-expire unused storage","description":"Storage that is no longer used still occupies hardware and carries embodied carbon. Deleting unused storage, either manually or through automated retention policies, reduces the hardware needed to hold data, provided deletion is controlled so that data still needed is not lost.","permalink":"/operations/resource-lifecycle/delete-or-auto-expire-unused-storage"},{"id":"operations/resource-lifecycle/optimise-storage-resource-utilisation","title":"Optimise storage utilization","description":"It\'s better to maximise storage utilisation so the storage layer is optimised for the task, not only in terms of energy proportionality but also in terms of embodied carbon. Two storage units running at low utilization rates will consume more energy than one running at a high utilization rate. In addition, the unused capacity on the underutilised storage unit could be more efficiently used for another task or process.","permalink":"/operations/resource-lifecycle/optimise-storage-resource-utilisation"},{"id":"development/data-handling/optimize-data-storage-ai-training","title":"Optimize data storage formats for AI training and inference","description":"Use efficient storage formats, compression, and indexing strategies for AI datasets and embeddings to reduce storage footprint, data transfer, and retrieval compute.","permalink":"/development/data-handling/optimize-data-storage-ai-training"}],"unlisted":false}}')}}]);